export const REVIVAL_DYNAMITE_EXPLOSION_VARIANT_COUNT = 3;
export const REVIVAL_DYNAMITE_ROLLING_VARIANT_COUNT = 3;
export const REVIVAL_DYNAMITE_ROLLING_LIFETIME = 6;
export const REVIVAL_DYNAMITE_SOURCE_SPRITES = Object.freeze([34,35,153,154,155,156,157,158,159,160,161,162,163,164,165,166,167,168,169,170,171,172,172,172]);
export const REVIVAL_DYNAMITE_OPAQUE_COUNTS = Object.freeze([100,101,100,99,98,99,97,98,97,96,97,98,95,94,99,142,147,168,257,353,492,451,403,314]);
export const REVIVAL_DYNAMITE_EXPLOSION_VARIANT_OPAQUE_COUNTS = Object.freeze([Object.freeze([168,257,353,492,451,403,314])]);
export const REVIVAL_DYNAMITE_ROLLING_OPAQUE_COUNTS = Object.freeze([168,208,345,349,354]);
const cache = new Map();
const rollingCache = new Map();

export function revivalDynamiteFrameIndex(role, ticker) {
  let value = Math.floor(Number(ticker) || 0);
  if (role === 'fuse') {
    value = Math.max(10, Math.min(45, value));
    if (value >= 40) return (value & 1) ? 1 : 0;
    return 2 + Math.floor((39 - value) / 2);
  }
  if (role === 'explosion') {
    value = Math.max(1, Math.min(9, value));
    if (value === 9) return 17;
    if (value === 8) return 18;
    if (value === 7) return 19;
    if (value === 6) return 20;
    if (value === 5) return 21;
    if (value >= 3) return 22;
    return 23;
  }
  return -1;
}

export function revivalDynamiteVariantFromSeed(seed) {
  let value = Number(seed) >>> 0;
  value = (value ^ (value >>> 16)) >>> 0;
  value = Math.imul(value, 0x7feb352d) >>> 0;
  value = (value ^ (value >>> 15)) >>> 0;
  return value % REVIVAL_DYNAMITE_EXPLOSION_VARIANT_COUNT;
}

function explosionVariantStage(stage, variant = 0) {
  const maps = [
    [0,1,2,3,4,5,6],
    [0,1,3,4,5,5,6],
    [0,1,1,2,3,4,6]
  ];
  const base = Math.max(0, Math.min(6, Math.floor(Number(stage) || 0)));
  return maps[(Number(variant) >>> 0) % REVIVAL_DYNAMITE_EXPLOSION_VARIANT_COUNT][base];
}

function decodedFrame(index, pn) {
  if (index < 0) return null;
  if (cache.has(index)) return cache.get(index);
  const indices = index < FUSE_FRAMES.length ? FUSE_FRAMES[index] : BLAST_FRAMES[index - FUSE_FRAMES.length];
  if (!indices) return null;
  const pixels = new PixelBuffer(WIDTH, HEIGHT, [0,0,0,0]);
  for (let i = 0; i < indices.length; i += 1) {
    const paletteIndex = indices[i];
    if (paletteIndex) pixels.setPixel(i % WIDTH, Math.floor(i / WIDTH), PALETTE[paletteIndex]);
  }
  const frame = Object.freeze({
    pixels, originX:28, originY:24, footAnchorX:28, footAnchorY:24,
    pn:Object.freeze({ index:Number(pn), source:'revival-player-dynamite' }),
    frameIndex:index, pfIndex:index, sourceSprite:REVIVAL_DYNAMITE_SOURCE_SPRITES[index]
  });
  cache.set(index, frame);
  return frame;
}

export function revivalDynamiteFrame(role, ticker, variant = 0) {
  let index = revivalDynamiteFrameIndex(role, ticker);
  if (index < 0) return null;
  if (role === 'explosion' && index >= FUSE_FRAMES.length)
    index = FUSE_FRAMES.length + explosionVariantStage(index - FUSE_FRAMES.length, variant);
  return decodedFrame(index, role === 'fuse' ? 36 : 41);
}

export function revivalRollingExplosionFrame(ageTicks, variant = 0) {
  const age = Math.max(0, Math.floor(Number(ageTicks) || 0));
  if (age >= REVIVAL_DYNAMITE_ROLLING_LIFETIME) return null;
  const maps = [[0,1,2,3,4],[0,1,3,4,4],[0,1,1,2,4]];
  const baseStage = age < 4 ? age : 4;
  const stage = maps[(Number(variant) >>> 0) % REVIVAL_DYNAMITE_ROLLING_VARIANT_COUNT][baseStage];
  if (rollingCache.has(stage)) return rollingCache.get(stage);
  const indices = ROLLING_FRAMES[stage];
  const pixels = new PixelBuffer(ROLLING_WIDTH, ROLLING_HEIGHT, [0,0,0,0]);
  for (let i = 0; i < indices.length; i += 1) {
    const paletteIndex = indices[i];
    if (paletteIndex) pixels.setPixel(i % ROLLING_WIDTH, Math.floor(i / ROLLING_WIDTH), PALETTE[paletteIndex]);
  }
  const frame = Object.freeze({
    pixels, originX:16, originY:18, footAnchorX:16, footAnchorY:18,
    pn:Object.freeze({ index:41, source:'revival-rolling-explosion' }),
    frameIndex:stage, pfIndex:stage, sourceSprite:null
  });
  rollingCache.set(stage, frame);
  return frame;
}

/* Research/editor PN ticks map to the authored cels only. Production weapon
 * presentation uses revivalDynamiteFrame() with xrick's native ticker. */
export function revivalDynamiteFrameForPn(pn, tick, variant = 0) {
  const id = Number(pn), value = Math.max(0, Number(tick) || 0);
  if (id === 36) {
    const index = Math.max(0, Math.min(16, Math.round(value * 16 / 71)));
    return decodedFrame(index, id);
  }
  if (id === 41) {
    const stage = explosionVariantStage(Math.round((value % 21) * 6 / 20), variant);
    return decodedFrame(17 + stage, id, variant);
  }
  return null;
}
